// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

uint256 constant VALUE_CAP = 1000000000000000000000000000000;

contract InvMutTest is Test {
    SimpleWallet c;

    function setUp() public {
        c = new SimpleWallet();
    }

    function testFuzz_property(uint256 amount) public {
        vm.assume(amount <= VALUE_CAP);
        // Fund c through its payable fallback (owner is this test contract).
        amount = bound(amount, 1, 1 ether);
        vm.deal(address(this), amount);
        (bool fed, ) = address(c).call{value: amount}("");
        assertTrue(fed);

        // Admissible domain: value must not exceed the contract balance so that
        // the reference's `transfer` cannot legitimately revert.
        vm.assume(amount <= address(c).balance);

        uint256 before = address(c).balance;
        vm.prank(address(this));
        bool ok; try c.withdraw(amount) { ok = true; } catch { ok = false; }
        assertTrue(ok);
        assertTrue(address(c).balance == before - amount);
    }

    receive() external payable {}
}
